import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.D7EuCHIT.js";const y=JSON.parse('{"title":"从这里开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/start.md","filePath":"guide/start.md","lastUpdated":1791818085000}'),s={name:"guide/start.md"};function i(l,t,o,n,h,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="从这里开始" tabindex="-1">从这里开始 <a class="header-anchor" href="#从这里开始" aria-label="Permalink to &quot;从这里开始&quot;">​</a></h1><p>Lyra Player 是闭源音乐播放器。插件使用公开 C ABI 与已安装宿主交互，开发者不需要取得、编译或修改播放器源码。</p><p>本站提供插件 SDK、可编译教程、配置参考与发布指南。当前为 SDK 2 / 接口版本 2 的文档预览；先看<a href="/LyraPlayer-docs-site/reference/snapshot">兼容范围</a>。</p><h2 id="选择你的路径" tabindex="-1">选择你的路径 <a class="header-anchor" href="#选择你的路径" aria-label="Permalink to &quot;选择你的路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>起点</th><th>产物</th></tr></thead><tbody><tr><td>第一次开发插件</td><td><a href="/LyraPlayer-docs-site/developers/build">准备环境</a>、<a href="/LyraPlayer-docs-site/plugins/first-plugin">第一个插件</a></td><td>可安装 ZIP</td></tr><tr><td>第三种播放样式</td><td><a href="/LyraPlayer-docs-site/plugins/styles">样式教程</a></td><td>样式声明与绘制</td></tr><tr><td>新播放模式</td><td><a href="/LyraPlayer-docs-site/plugins/rules">规则教程</a></td><td>模式、next 与真实队列</td></tr><tr><td>可调整插件参数</td><td><a href="/LyraPlayer-docs-site/plugins/config-schema">schema 教程</a></td><td>带说明与校验的参数</td></tr><tr><td>音频解码扩展</td><td><a href="/LyraPlayer-docs-site/plugins/playback">提供者</a></td><td>音频后端及主时钟</td></tr><tr><td>媒体源与分类</td><td><a href="/LyraPlayer-docs-site/plugins/data">数据接口</a></td><td>目录或分类规则</td></tr><tr><td>自定义字号/主题</td><td><a href="/LyraPlayer-docs-site/config/getting-started">配置入门</a></td><td>覆盖配置</td></tr><tr><td>发布插件</td><td><a href="/LyraPlayer-docs-site/plugins/manifest">包清单</a>、<a href="/LyraPlayer-docs-site/plugins/publishing">发布</a></td><td>包、元数据与分发</td></tr></tbody></table><h2 id="独立工作区" tabindex="-1">独立工作区 <a class="header-anchor" href="#独立工作区" aria-label="Permalink to &quot;独立工作区&quot;">​</a></h2><p><code>LyraPlayer-docs</code> 是独立文档 workspace。包含网站、公开 SDK 和插件示例，网站本身不进入播放器安装包。运行文档需要 Node.js，安装或使用插件不需要。</p><p><a href="/LyraPlayer-docs-site/downloads/lyra-plugin-sdk.zip">下载 SDK 与示例</a>。先从 style/rules 示例入手；根替换实验可能隐藏默认卸载入口。</p><h2 id="当前边界" tabindex="-1">当前边界 <a class="header-anchor" href="#当前边界" aria-label="Permalink to &quot;当前边界&quot;">​</a></h2><p>原生插件是进程内可信代码，不是沙箱。支持服务替换与样式/模式/参数声明；不公开宿主私有对象和 GPU 句柄。当前插件产物是 Android arm64-v8a，PC 宿主尚未发布。默认字号可配置，全局自定义字体 UI 不属于当前已实现承诺。</p>',10)])])}const u=a(s,[["render",i]]);export{y as __pageData,u as default};
